const $=id=>document.getElementById(id),labels={outdoor:'Ao ar livre',treadmill:'Esteira',other:'Outro local'};
let features,analytics;
let db,sessions=[],current=null,profile={},watch=null,map=null,layers=null,storageOK=false,saveChain=Promise.resolve(),messageTimer,previewMap=null,previewLayers=null;
const number=(v,n=2)=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:n,maximumFractionDigits:n});
const clock=ms=>{const s=Math.floor(ms/1000);return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(x=>String(x).padStart(2,'0')).join(':');};
function notify(text,error=false){clearTimeout(messageTimer);$('message').textContent=text;$('message').hidden=false;$('message').classList.toggle('error',error);messageTimer=setTimeout(()=>$('message').hidden=true,7000);}
function request(store,mode,fn){return new Promise((resolve,reject)=>{let tx=db.transaction(store,mode);const req=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Salvamento interrompido'));});}
function persist(){features?.pending();const snapshot=structuredClone({sessions,profile});saveChain=saveChain.catch(()=>{}).then(()=>request('data','readwrite',s=>s.put(snapshot,'state'))).then(result=>{storageOK=true;return result;});saveChain.catch(()=>{storageOK=false;notify('Não foi possível salvar. Exporte um backup antes de sair.',true);});return saveChain;}
function page(name){for(const id of ['today','session','history','analytics','profile'])$(id).hidden=id!==name;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name||(name==='session'&&b.dataset.page==='today')));if(name==='history')renderHistory();if(name==='analytics')analytics?.render();if(name==='today')setTimeout(()=>previewMap?.invalidateSize(),100);if(name==='session'){renderLive();setTimeout(()=>map?.invalidateSize(),100);}window.scrollTo({top:0});}
function stopGPS(){if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}}
function drawMap(){if(!current)return;if(!globalThis.L){$('map').hidden=true;$('map-fallback').hidden=false;return;}try{$('map').hidden=false;$('map-fallback').hidden=true;if(!map){map=L.map('map',{scrollWheelZoom:false}).setView([-15.78,-47.93],4);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);layers=L.layerGroup().addTo(map);}layers.clearLayers();let bounds=[];for(const seg of current.segments){if(!seg.length)continue;let pts=seg.map(p=>[p.lat,p.lng]);bounds.push(...pts);L.polyline(pts,{color:'#16866b',weight:5,opacity:.9}).addTo(layers);L.circleMarker(pts[0],{radius:5,color:'#146b58',fillColor:'#fff',fillOpacity:1}).addTo(layers);}if(bounds.length){L.circleMarker(bounds.at(-1),{radius:7,color:'#fff',weight:2,fillColor:'#146b58',fillOpacity:1}).addTo(layers);if(bounds.length===1)map.setView(bounds[0],16);else map.fitBounds(bounds,{padding:[25,25],maxZoom:17});}}catch{$('map').hidden=true;$('map-fallback').hidden=false;}}
async function startGPS(){stopGPS();if(!current?.useGPS||current.status!=='active')return;if(!navigator.geolocation){$('gps-status').textContent='Localização não disponível neste navegador.';$('retry-gps').hidden=false;return;}$('gps-status').textContent='Buscando localização… o cronômetro já está funcionando.';loadMaps().then(()=>{if(current?.useGPS&&current.status==='active')drawMap();}).catch(()=>{$('map-fallback').hidden=false;});watch=navigator.geolocation.watchPosition(p=>{if(!current||current.status!=='active')return;let point;try{point=positionFix(p);}catch(error){$('gps-status').textContent=locationError(error);return;}$('retry-gps').hidden=true;const accepted=addPoint(current,point);$('gps-status').textContent=p.coords.accuracy>35?'Sinal impreciso. Aguardando um ponto melhor.':`GPS ativo · precisão aproximada de ${Math.round(p.coords.accuracy)} m`;if(accepted){persist();renderLive();drawMap();}},e=>{$('gps-status').textContent=locationError(e);$('retry-gps').hidden=false;if(e.code===1)stopGPS();},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
function renderLive(){if(!current)return;const t=elapsed(current);$('timer').textContent=clock(analyze(current,profile).active);$('timer-label').textContent=current.correctedMinutes?'TEMPO ATIVO · CORRIGIDO':'TEMPO ATIVO';$('pause-time').textContent='Pausas: '+clock(t.paused);const metrics=sessionMetrics(current,profile);$('distance').textContent=metrics.km===null?'—':number(metrics.km);$('steps').textContent=metrics.steps===null?(metrics.stepsRange?'≈ '+metrics.stepsRange.map(n=>n.toLocaleString('pt-BR')).join('–'):'—'):metrics.steps.toLocaleString('pt-BR');$('calories').textContent=metrics.kcal===null?'—':number(metrics.kcal,0);$('distance-source').textContent='km · '+metrics.kmSource;$('session-kind').textContent=labels[current.kind];const plan=current.plannedRhythms||[];$('session-plan').textContent=plan.length?'Planejado: '+number(plan.reduce((n,t)=>n+t.distance,0))+' km · '+number(plan.reduce((n,t)=>n+t.minutes,0),1)+' min · '+plan.length+' trecho(s). O realizado aparece abaixo.':'';$('session-state').textContent=current.status==='paused'?'Pausada':'Em andamento';$('pause').textContent=current.status==='paused'?'Continuar caminhada':'Pausar caminhada';$('gaps').textContent=current.gaps.length?`${current.gaps.length} intervalo(s) sem coleta. A rota não liga esses trechos.`:'';}
function renderToday(){const today=new Date().toLocaleDateString('pt-BR'),done=sessions.filter(s=>s.status==='finished'&&new Date(s.start).toLocaleDateString('pt-BR')===today),metrics=done.map(s=>sessionMetrics(s,profile)),known=metrics.filter(m=>m.km!==null);$('greeting').textContent=profile.name?'Olá, '+profile.name+'. Vamos nos mover?':'Seu momento de movimento';$('today-distance').replaceChildren(document.createTextNode((known.length?number(known.reduce((n,m)=>n+m.km,0)):'—')+' '));const small=document.createElement('small');small.textContent='km';$('today-distance').append(small);$('distance-caption').textContent=known.length?'Distância realizada · GPS e/ou informada'+(known.length<done.length?' · há sessões sem distância':''):'Finalize e registre uma caminhada para ver aqui.';$('today-time').textContent=Math.floor(metrics.reduce((n,m)=>n+m.active,0)/60000)+' min em movimento';$('today-count').textContent=done.length?`${done.length} caminhada${done.length>1?'s':''}`:'Nenhuma caminhada';$('start').textContent=current?'Voltar à caminhada':'Iniciar caminhada ↗';const rows=weeklyActivity(sessions),max=Math.max(1,...rows.map(r=>r.minutes)),chart=$('week-chart');chart.replaceChildren();const total=rows.reduce((n,r)=>n+r.minutes,0);$('week-total').textContent=Math.floor(total)+' min';chart.setAttribute('aria-label',rows.map(r=>r.label+': '+Math.round(r.minutes)+' minutos').join('; '));rows.forEach((r,i)=>{const day=document.createElement('div');day.className='chart-day';day.title=r.key+' · '+Math.round(r.minutes)+' min';const track=document.createElement('div');track.className='bar-track';const bar=document.createElement('div');bar.className='bar'+(r.minutes?'':' zero');bar.style.setProperty('--bar-height',(r.minutes/max*72)+'px');bar.style.setProperty('--delay',(i*35)+'ms');track.append(bar);const label=document.createElement('span');label.textContent=r.label;day.append(track,label);chart.append(day);});$('week-note').textContent=rows.some(r=>r.count)?'Somente sessões finalizadas. Dias sem registro não comprovam inatividade.':'Finalize uma caminhada para acompanhar seu tempo ativo.';}
function renderHistory(){const list=$('history-list');list.replaceChildren();const done=(features?.filtered()??sessions.filter(s=>s.status==='finished')).sort((a,b)=>b.start-a.start);if(!done.length){const empty=document.createElement('div');empty.className='empty';const strong=document.createElement('strong');strong.textContent='Seu primeiro percurso começa aqui.';empty.append(strong,document.createTextNode('Inicie uma caminhada para guardar seu tempo e movimento.'));list.append(empty);}for(const s of done){const d=document.createElement('details');d.className='history-item';const sum=document.createElement('summary');const metrics=sessionMetrics(s,profile);sum.textContent=labels[s.kind]+' · '+(metrics.km===null?'Sem distância registrada':number(metrics.km)+' km');const sub=document.createElement('small');sub.textContent=new Date(s.start).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})+' · '+clock(metrics.active);sum.append(sub);d.append(sum);for(const txt of ['Tempo pausado: '+clock(elapsed(s).paused)+(s.correctedMinutes?' · Tempo ativo corrigido; original: '+clock(elapsed(s).active):''),s.useGPS?'Percurso: GPS · '+s.segments.flat().length+' pontos válidos':'Percurso não registrado nesta sessão',s.gaps.length?`${s.gaps.length} intervalo(s) sem coleta. Tempo ativo pode incluir lacunas.`:'',s.notes?'Observação: '+s.notes:'']){if(!txt)continue;const p=document.createElement('p');p.textContent=txt;d.append(p);}const r=analyze(s,profile);const summary=document.createElement('p');summary.textContent='Calorias ativas estimadas: '+(r.kcal===null?'—':number(r.kcal,0)+' kcal')+' · Degraus: '+r.stairCount;d.append(summary);if(r.issues.length){const warning=document.createElement('p');warning.textContent=r.issues.join(' ');d.append(warning);}const edit=document.createElement('button');edit.type='button';edit.className='secondary';edit.textContent='Detalhar ou corrigir';edit.onclick=()=>features.openDetails(s);d.append(edit);list.append(d);}$('export').disabled=!sessions.length;}
$('start-form').addEventListener('submit',async e=>{e.preventDefault();if(current){page('session');return;}if(!(profile.height>0&&profile.weight>0&&profile.age>0)){page('profile');notify('Antes de começar, informe altura, peso e idade no perfil.');return;}if(!storageOK){notify('Armazenamento indisponível. Não é seguro iniciar antes de corrigir.',true);return;}let plannedRhythms;try{plannedRhythms=$('interval').value==='yes'?readRhythms($('plan-rhythms')):[];}catch(error){notify(error.message,true);return;}$('start').disabled=true;current=createSession($('kind').value);current.interval=$('interval').value==='yes';current.pace='';current.plannedRhythms=plannedRhythms;current.profileSnapshot=payloadOf(structuredClone(profile));current.useGPS=$('gps').checked&&current.kind!=='treadmill';sessions.push(current);try{await persist();$('notes').value='';$('recovery').hidden=true;page('session');$('gps-status').textContent=current.kind==='treadmill'?'Esteira: GPS desligado. Use Detalhar caminhada para informar velocidades, durações e quilômetros do painel.':'Localização desativada para esta sessão.';$('map').hidden=true;$('map-fallback').hidden=true;startGPS();renderToday();}catch{sessions=sessions.filter(s=>s.id!==current.id);current=null;notify('Não foi possível iniciar com salvamento local.',true);}finally{$('start').disabled=false;}});
$('pause').onclick=async()=>{if(!current)return;transition(current,current.status==='active'?'pause':'resume');if(current.status==='paused'){stopGPS();$('gps-status').textContent='Coleta de localização pausada.';}else startGPS();renderLive();await persist().catch(()=>{});};
$('finish').onclick=()=>{$('finish-dialog').returnValue='';$('finish-dialog').showModal();};
$('finish-dialog').addEventListener('close',async()=>{if($('finish-dialog').returnValue!=='finish'||!current)return;stopGPS();transition(current,'finish');current.notes=$('notes').value;current.analysis=analyze(current,profile);try{await persist();current=null;$('recovery').hidden=true;renderToday();page('history');notify('Caminhada salva no aparelho.');features.afterSave();}catch{notify('Sessão encerrada, mas o salvamento falhou. Exporte o backup agora.',true);current=null;renderToday();page('history');}});
$('notes').addEventListener('input',()=>{if(current){current.notes=$('notes').value;$('stairs-hint').hidden=!/escad/i.test(current.notes);persist();}});
document.querySelectorAll('.place').forEach(b=>b.onclick=()=>{document.querySelectorAll('.place').forEach(p=>{p.classList.toggle('selected',p===b);p.setAttribute('aria-pressed',String(p===b));});$('kind').value=b.dataset.kind;$('gps').disabled=b.dataset.kind==='treadmill';$('gps-row').hidden=b.dataset.kind==='treadmill';$('gps').checked=b.dataset.kind!=='treadmill';});
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page==='today'&&current?'session':b.dataset.page));
function updateTheme(){const dark=document.documentElement.dataset.theme==='dark';$('theme').setAttribute('aria-label',dark?'Ativar tema claro':'Ativar tema escuro');}updateTheme();$('theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('borali-theme',document.documentElement.dataset.theme);}catch{notify('Tema alterado; preferência não pôde ser salva.');}updateTheme();};
$('profile-form').onsubmit=async e=>{e.preventDefault();profile={...profile,name:$('name').value.trim(),stride:$('stride').value?Number($('stride').value):null,height:$('height').value?Number($('height').value):null,weight:$('weight').value?Number($('weight').value):null,age:$('age').value?Number($('age').value):null,sex:$('sex').value};try{await persist();notify('Ajustes salvos neste navegador.');renderToday();renderLive();features.afterSave();}catch{}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({product:'Borali',version:1,exportedAt:new Date().toISOString(),sessions,profile},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='borali-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
let hiddenAt=null;document.addEventListener('visibilitychange',()=>{if(!current)return;if(document.hidden){hiddenAt=Date.now();stopGPS();persist();}else{if(hiddenAt&&current.status==='active'){current.gaps.push({from:hiddenAt,to:Date.now()});current.segments.push([]);$('recovery').hidden=false;notify('Você voltou. O intervalo sem coleta ficou identificado; o tempo pode incluir esse período.');persist();}hiddenAt=null;startGPS();renderLive();}});
window.addEventListener('pagehide',stopGPS);window.addEventListener('online',()=>{notify('Conexão disponível. Use Sincronizar agora no perfil para conferir a nuvem.');});
appendRhythm($('plan-rhythms'));$('add-plan-rhythm').onclick=()=>appendRhythm($('plan-rhythms'),{},{removable:true});function toggleIntervalPlanning(){const enabled=$('interval').value==='yes';$('rhythm-planning').hidden=!enabled;$('add-plan-rhythm').hidden=!enabled;for(const control of $('rhythm-planning').querySelectorAll('input,button,select'))control.disabled=!enabled;} $('interval').onchange=toggleIntervalPlanning;toggleIntervalPlanning();$('retry-gps').onclick=()=>{if(current?.status==='active')startGPS();else notify('Continue a caminhada para retomar a localização.');};
$('locate-now').onclick=async()=>{$('locate-now').disabled=true;$('location-status').textContent='Buscando sua posição… autorize o acesso quando o navegador perguntar.';try{const p=await locate();$('location-status').textContent='Localização obtida · precisão aproximada de '+Math.round(p.accuracy)+' m. '+(p.accuracy>35?'O sinal ainda é insuficiente para medir o percurso com confiança.':'');const L=await loadMaps();$('preview-map').hidden=false;if(!previewMap){previewMap=L.map('preview-map',{scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(previewMap);previewLayers=L.layerGroup().addTo(previewMap);}previewLayers.clearLayers();L.circle([p.lat,p.lng],{radius:p.accuracy,color:'#146b58',weight:1,fillOpacity:.1}).addTo(previewLayers);L.circleMarker([p.lat,p.lng],{radius:8,color:'#fff',fillColor:'#146b58',fillOpacity:1}).bindTooltip('Você está aqui').addTo(previewLayers);previewMap.setView([p.lat,p.lng],16);setTimeout(()=>previewMap.invalidateSize(),100);}catch(error){$('location-status').textContent=locationError(error);}finally{$('locate-now').disabled=false;}};
$('date').textContent=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});$('start').disabled=true;
analytics=setupAnalytics(()=>({sessions,profile}));$('open-analytics').onclick=()=>page('analytics');
features=setupFeatures({getState:()=>({sessions,profile,current}),setState:r=>{sessions=r.sessions;profile=r.profile;fillProfile();},save:persist,refresh:()=>{renderToday();renderLive();if(!$('history').hidden)renderHistory();if(!$('analytics').hidden)analytics.render();},notify});
function fillProfile(){for(const id of ['name','stride','height','weight','age','sex'])$(id).value=profile[id]??'';}
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('borali-technical-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Banco bloqueado'));});const state=await request('data','readonly',s=>s.get('state'));if(state){sessions=state.sessions||[];profile=state.profile||{};}storageOK=true;$('start').disabled=false;current=sessions.find(s=>s.status!=='finished')||null;fillProfile();if(current){if(current.status==='active'){const last=current.segments.flat().at(-1)?.t??current.events.at(-1).t;current.gaps.push({from:last,to:Date.now()});current.segments.push([]);transition(current,'pause');}await persist();$('notes').value=current.notes||'';$('recovery').hidden=false;page('session');$('gps-status').textContent='Sessão recuperada e pausada. Confira o tempo; retomada depende da sua ação.';}renderToday();}catch{notify('Armazenamento local indisponível. O início foi bloqueado para proteger seus dados.',true);}
setInterval(renderLive,1000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>notify('Modo offline não pôde ser ativado. Use com conexão.'));
